//! National language support: the system country and code pages
//! (CONFIG.SYS `COUNTRY=` and `CODEPAGE=`), process code pages, country
//! information, case maps, collating sequences and DBCS ranges.
//!
//! The tables come from `nls_data.rs` (generated by
//! tools/scripts/gen_nls.py). As on OS/2, a process may only switch to
//! one of the two prepared code pages (`CODEPAGE=primary,secondary`);
//! without a CODEPAGE statement the prepared pair is the country's
//! default.

use alloc::collections::BTreeMap;

use crate::codepage::CodePage;
use crate::nls_data::{Country, COLLATE, COUNTRIES, DBCS, UCASE};
use crate::sync::SpinLock;

pub const ERROR_INVALID_CODE_PAGE: u32 = 472;
pub const ERROR_NLS_NO_CTRY_CODE: u32 = 398;
pub const ERROR_VIO_BAD_CP: u32 = 469;
pub const ERROR_KBD_INVALID_CODEPAGE: u32 = 448;

struct System {
    country: u16,
    /// Prepared code pages (primary, secondary; 0 = none).
    prepared: [u16; 2],
    /// Process code pages that differ from their parent's.
    process: BTreeMap<u32, u16>,
}

static SYSTEM: SpinLock<System> =
    SpinLock::new(System { country: 1, prepared: [850, 437], process: BTreeMap::new() });

/// Apply CONFIG.SYS: `COUNTRY=nnn[,file]` and `CODEPAGE=p[,s]`.
pub fn configure(country: Option<u16>, codepages: &[u16]) {
    let mut s = SYSTEM.lock();
    if let Some(c) = country.filter(|&c| find_country(c).is_some()) {
        s.country = c;
        if codepages.is_empty() {
            s.prepared = find_country(c).map_or([850, 437], |c| c.codepages);
        }
    }
    let ok: alloc::vec::Vec<u16> = codepages.iter().copied().filter(|&cp| known(cp)).take(2).collect();
    if !ok.is_empty() {
        s.prepared = [ok[0], ok.get(1).copied().unwrap_or(0)];
    }
    let primary = s.prepared[0];
    drop(s);
    // The screen starts in the primary code page if it can show it.
    if let Some(cp) = CodePage::from_number(primary) {
        crate::screen::with(|s| s.set_codepage(cp));
    }
    crate::kbd::layout::set_codepage(primary);
}

pub fn system_country() -> u16 {
    SYSTEM.lock().country
}

/// The prepared system code pages (a 0 entry is absent).
pub fn prepared() -> [u16; 2] {
    SYSTEM.lock().prepared
}

pub fn is_prepared(cp: u16) -> bool {
    cp != 0 && prepared().contains(&cp)
}

/// A code page rs2 has tables for (single- or double-byte).
pub fn known(cp: u16) -> bool {
    CodePage::from_number(cp).is_some() || is_dbcs(cp)
}

pub fn find_country(code: u16) -> Option<&'static Country> {
    COUNTRIES.iter().find(|c| c.code == code)
}

/// The code page of a process: its own setting, else its parent's, else
/// the primary system code page.
pub fn process_cp(pid: u32) -> u16 {
    let mut pid = pid;
    for _ in 0..64 {
        if let Some(&cp) = SYSTEM.lock().process.get(&pid) {
            return cp;
        }
        match crate::task::process::by_pid(pid) {
            Some(p) if p.ppid != 0 && p.ppid != pid => pid = p.ppid,
            _ => break,
        }
    }
    prepared()[0]
}

/// DosSetProcessCp: switch to one of the prepared code pages.
pub fn set_process_cp(pid: u32, cp: u16) -> Result<(), u32> {
    if !is_prepared(cp) {
        return Err(ERROR_INVALID_CODE_PAGE);
    }
    let mut s = SYSTEM.lock();
    // Forget processes that have ended.
    if s.process.len() > 64 {
        s.process.retain(|&p, _| crate::task::process::by_pid(p).is_some());
    }
    s.process.insert(pid, cp);
    Ok(())
}

/// Resolve a COUNTRYCODE: 0 means the system country / the process's
/// code page. Unknown countries or code pages are ERROR_NLS_NO_CTRY_CODE.
pub fn resolve(pid: u32, country: u32, cp: u32) -> Result<(u16, u16), u32> {
    let country = if country == 0 { system_country() } else { country as u16 };
    let cp = if cp == 0 { process_cp(pid) } else { cp as u16 };
    if find_country(country).is_none() || !known(cp) {
        return Err(ERROR_NLS_NO_CTRY_CODE);
    }
    Ok((country, cp))
}

/// Country information as OS/2 returns it: COUNTRYINFO (44 bytes, 32-bit)
/// or the 16-bit layout (38 bytes).
pub fn country_info(country: u16, cp: u16, is16: bool) -> alloc::vec::Vec<u8> {
    let c = find_country(country).unwrap_or(&COUNTRIES[0]);
    let mut b = alloc::vec::Vec::new();
    if is16 {
        b.extend_from_slice(&country.to_le_bytes());
        b.extend_from_slice(&cp.to_le_bytes());
        b.extend_from_slice(&(c.date_fmt as u16).to_le_bytes());
    } else {
        b.extend_from_slice(&(country as u32).to_le_bytes());
        b.extend_from_slice(&(cp as u32).to_le_bytes());
        b.extend_from_slice(&(c.date_fmt as u32).to_le_bytes());
    }
    let mut cur = [0u8; 5];
    let enc = encode(c.currency, cp).filter(|e| e.len() <= 4);
    let s = enc.as_deref().unwrap_or(c.currency_ascii.as_bytes());
    cur[..s.len().min(4)].copy_from_slice(&s[..s.len().min(4)]);
    b.extend_from_slice(&cur);
    for sep in [c.thousands, c.decimal, c.date_sep, c.time_sep] {
        b.extend_from_slice(&[sep, 0]);
    }
    b.extend_from_slice(&[c.currency_fmt, c.decimals, c.time_fmt]);
    b.extend_from_slice(&[0; 4]);
    b.extend_from_slice(&[c.list_sep, 0]);
    b.extend_from_slice(&[0; 10]);
    b
}

/// Encode a string in a single-byte code page (None if a character is
/// missing or the code page is not single-byte).
fn encode(s: &str, cp: u16) -> Option<alloc::vec::Vec<u8>> {
    if s.is_ascii() {
        return Some(s.as_bytes().into());
    }
    let page = CodePage::from_number(cp)?;
    s.chars().map(|ch| page.from_char(ch)).collect()
}

/// The 256-byte upper-case table of a country and code page.
pub fn case_map(country: u16, cp: u16) -> [u8; 256] {
    let mut t = [0u8; 256];
    for (i, v) in t.iter_mut().enumerate() {
        *v = (i as u8).to_ascii_uppercase();
    }
    let high = UCASE
        .iter()
        .find(|e| e.0 == country && e.1 == cp)
        .or_else(|| UCASE.iter().find(|e| e.0 == 0 && e.1 == cp));
    if let Some(e) = high {
        t[128..].copy_from_slice(&e.2);
    }
    t
}

/// Upper case of one byte in the process's terms.
pub fn upper(country: u16, cp: u16, b: u8) -> u8 {
    case_map(country, cp)[b as usize]
}

/// The collating weights of a country and code page.
pub fn collate(country: u16, cp: u16) -> [u8; 256] {
    let e = COLLATE
        .iter()
        .find(|e| e.0 == country && e.1 == cp)
        .or_else(|| COLLATE.iter().find(|e| e.0 == 0 && e.1 == cp));
    match e {
        Some(e) => e.2,
        None => {
            let mut t = [0u8; 256];
            for (i, v) in t.iter_mut().enumerate() {
                *v = (i as u8).to_ascii_uppercase();
            }
            t
        }
    }
}

/// DBCS lead byte ranges (empty for single-byte code pages).
pub fn dbcs_ranges(cp: u16) -> &'static [(u8, u8)] {
    DBCS.iter().find(|e| e.0 == cp).map_or(&[], |e| e.1)
}

pub fn is_dbcs(cp: u16) -> bool {
    !dbcs_ranges(cp).is_empty()
}

/// Screen code page switch for VioSetCp: 0 selects the primary code
/// page; only prepared code pages that the screen font can show are
/// accepted.
pub fn screen_cp(cp: u16) -> Result<CodePage, u32> {
    let cp = if cp == 0 { prepared()[0] } else { cp };
    if !is_prepared(cp) {
        return Err(ERROR_VIO_BAD_CP);
    }
    CodePage::from_number(cp).ok_or(ERROR_VIO_BAD_CP)
}

/// Keyboard code page switch for KbdSetCp (0 = the primary code page).
pub fn keyboard_cp(cp: u16) -> Result<u16, u32> {
    let cp = if cp == 0 { prepared()[0] } else { cp };
    if !is_prepared(cp) || CodePage::from_number(cp).is_none() {
        return Err(ERROR_KBD_INVALID_CODEPAGE);
    }
    Ok(cp)
}
